#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int n, k;
    if (cin >> n >> k) {
        vector<int> a(n);
        for (int i = 0; i < n; ++i) cin >> a[i];
        int target = a[k - 1];
        int cnt = 0;
        for (int i = 0; i < n; ++i) {
            if (a[i] >= target && a[i] > 0) cnt++;
        }
        cout << cnt << "\n";
    }
    return 0;
}
